#!/usr/bin/env python3
"""Build a deterministic, fail-closed plan from compiled Windows test binaries."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import sys
from collections import defaultdict
from pathlib import Path, PurePosixPath
from typing import Any, Iterable


SETTINGS_SCHEMA = "entire-brain.windows-ci.settings.v1"
WEIGHTS_SCHEMA = "entire-brain.windows-ci.historical-weights.v1"
INVENTORY_SCHEMA = "entire-brain.windows-ci.compiled-inventory.v1"
PLAN_SCHEMA = "entire-brain.windows-ci.shard-plan.v1"
ROOT_KINDS = ("Test", "Example", "Fuzz")
_TIMEOUT = re.compile(r"^[1-9][0-9]*(?:ns|us|µs|ms|s|m|h)$")
_SHA = re.compile(r"^[0-9a-f]{40}$")
_SHA256 = re.compile(r"^[0-9a-f]{64}$")
TARGET_ENVIRONMENT = {"GOOS": "windows", "GOARCH": "amd64", "CGO_ENABLED": "1"}


def read_json(path: Path) -> Any:
    try:
        with path.open(encoding="utf-8-sig") as handle:
            return json.load(handle)
